function findComplement(num) {
  // Spell out the bits, swap each character, and read the result back.
  const bits = num.toString(2);
  let flipped = '';
  for (const bit of bits) flipped += bit === '1' ? '0' : '1';
  return parseInt(flipped, 2);
}

