function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [1 + pick(2147483647)];
  const style = pick(4);
  if (style === 0) return [1 + pick(64)];
  // A power of two or a run of ones: the two extremes of the flip.
  if (style === 1) return [2 ** pick(31)];
  if (style === 2) return [2 ** (1 + pick(31)) - 1];
  // Any bit length from 1 to 31, with the top bit set.
  const length = 1 + pick(31);
  return [2 ** (length - 1) + pick(2 ** (length - 1))];
}
